@import '../../../theme/web/custom-variables';

.ux-policies-web { 
  &.ux-application-content-zoom {
    zoom: 150% !important;

    .widget-customDropdown-holder {
      width: 210px !important;
    }
  
    /* Fix tooltip positioning broken by zoom */
    .widget-tooltip-content {
      zoom: calc(1 / 1.5) !important;
      transform-origin: top left;
    }
    
    .workarea-type span.mx-text {
      color: #1E1E1E !important;
      font-family: "Segoe UI" !important;
      font-size: 17.28px !important;
      font-style: normal !important;
