div[id=content]:has(.ux-application-content-zoom) ~ div.swal2-container {
  zoom: 150% !important;
  padding: 43px 24px 0 0 !important;
}

/* ========================================
   TILE BUTTON GRID LAYOUT
   ======================================== */
.ux-tile-button {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(178px, 1fr));
  align-items: flex-start;
  align-content: flex-start;
  padding: 0;
  gap: 16px;

  /* Icon size inside links and buttons */
  .mx-link img, .mx-button img {
    height: 24px;
  }

  /* Base button styles */
  .btn,
  .mx-button {
    box-sizing: border-box;
    padding: 8px 16px;
    width: 100%;
    min-width: 178px;
    height: 50px;
    min-height: 40px;

    font: normal normal 600 25.92px / 36px 'Segoe UI';
    border: 1px solid rgba(0, 0, 0, 0.15);

    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 8px;

    &:focus {
      outline: none !important;
    }
  }

  /* Default state */
  .btn-default {
    color: #007993;

    &:hover {
      background: #daecf0;
    }

    &:active {
      background: #005F87;
    }

    &:focus {
      background: #EEF6F8;
      color: #007993;
    }
  }

  /* Selected state */
  .selected-button {
    background: #EEF6F8;
    color: #007993;

    &:hover {
      background: #daecf0;
    }
  }

  /* Disabled state */
  .disabled-button {
    pointer-events: none !important;
    background: rgba(0, 0, 0, 0.15) !important;
    border: 1px solid rgba(0, 0, 0, 0.15) !important;
    color: rgba(0, 0, 0, 0.3) !important;
  }
}

/* ========================================
   SIGN IN & SIGN OUT BUTTONS
   ======================================== */

/* Enabled state */
.ux-accordion .btn.btn-sign.btn-default,
.ux-accordion .mx-button.btn-sign.btn-default {
    color: #FFFFFF !important;
    background: #005F87 !important;
    border: 1px solid #003750 !important;
    
    width: 85px !important;
    height: 35px !important;
    min-width: 85px !important;
    max-width: 85px !important;
    
    padding: 4px 8px !important;
    border-radius: 2px !important;
    
    &:hover {
      background: #004A6B !important;
    }

    &:active {
      background: #003750 !important;
    }

    &:focus {
      background: #005F87 !important;
      color: #FFFFFF !important;
    }
}

/* Disabled state */
.ux-accordion .btn.btn-sign.disabled-button,
.ux-accordion .mx-button.btn-sign.disabled-button {
    pointer-events: none !important;
    cursor: not-allowed !important;
    
    background: rgba(0, 0, 0, 0.15) !important;
    border: 1px solid rgba(0, 0, 0, 0.15) !important;
    color: rgba(0, 0, 0, 0.3) !important;
    
    width: 85px !important;
    height: 35px !important;
    padding: 4px 8px !important;
    border-radius: 2px !important;
    
    &:hover,
    &:active,
    &:focus {
      background: rgba(0, 0, 0, 0.15) !important;
      border: 1px solid rgba(0, 0, 0, 0.15) !important;
      color: rgba(0, 0, 0, 0.3) !important;
      outline: none !important;
      box-shadow: none !important;
    }
}

/* ========================================
   TEXT BOX LABEL
   ======================================== */
.mx-name-opcenterCoreTextBox1 .control-label,
.mx-name-opcenterCoreTextBox2 .control-label {
    color: #1E1E1E;
    font-family: "Segoe UI";
    font-size: 12px;
    font-style: normal;
    font-weight: 600;
    line-height: 16px;
}

/* ========================================
   PANEL SECTION - GROUP BOX CONTAINER
   ======================================== */
.panel-section {
    display: flex;
    flex-direction: column;
    width: 100%;
    padding: 4px 8px !important;
    box-sizing: border-box;
    position: relative !important;
    border-radius: 4px;
    border: 1px solid rgba(0, 0, 0, 0.15);
    background: #FFF;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.30);
}

/* Reset internal padding and margins for all direct children */
.panel-section > *,
.panel-section .mx-groupbox-header,
.panel-section .mx-groupbox-header *,
.panel-section .mx-groupbox-body {
    padding: 0 !important;
    margin: 0 !important;
}

/* Remove layout grid side padding */
.panel-section .mx-layoutgrid {
    padding-left: 0px !important;
    padding-right: 0px !important;
}

.panel-section .panel-section-content,
.panel-section > .panel-section-content,
.panel-section .mx-groupbox-body .panel-section-content {
    margin: 0 !important;
}

/* ========================================
   PANEL SECTION - COLLAPSE ICON
   ======================================== */

/* Expanded state - shows down arrow */
.panel-section .mx-groupbox-header > .mx-groupbox-collapse-icon {
    display: inline-block !important;
    
    font-size: 0;
    text-indent: -9999px;
    overflow: hidden;

    width: 24px !important;
    height: 24px !important;
    background-image: url('/img/EXCR_DesignSystem$Icon_Repository$miscDownArrowBlack16.svg') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    
    margin-right: 8px !important;
    margin-left: 0 !important;
    vertical-align: middle !important;
    flex-shrink: 0 !important;
    
    transition: background-image 0.2s ease !important;
}

/* Collapsed state - shows right arrow */
.panel-section.collapsed .mx-groupbox-header .mx-groupbox-collapse-icon,
.panel-section.mx-groupbox-collapsed .mx-groupbox-header .mx-groupbox-collapse-icon {
    background-image: url('/img/EXCR_DesignSystem$Icon_Repository$miscRightArrow16.svg') !important;
}

/* ========================================
   PANEL SECTION - HEADER
   ======================================== */
.panel-section .mx-groupbox-header {
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;
    background: #FFF !important;
    background-color: #FFF !important;
    width: 100% !important;
    padding: 8px 8px !important;
    padding-right: 100px !important;
    min-height: 56px !important;

    overflow: visible !important;
    color: #1E1E1E !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
    
    font-family: "Segoe UI" !important;
    font-size: 14.4px;
    font-style: normal !important;
    font-weight: 600 !important;
    line-height: 19px;
}

/* Edge-to-edge separator line below header using pseudo-element */
.panel-section .mx-groupbox-header::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: -8px;
    right: -8px;
    height: 1px;
    background-color: rgba(0, 0, 0, 0.15);
}

/* Hide separator line when panel is collapsed */
.panel-section.collapsed .mx-groupbox-header::after,
.panel-section.mx-groupbox-collapsed .mx-groupbox-header::after {
    display: none;
}

/* Header text content */
.panel-section .mx-groupbox-header .mx-groupbox-header-content,
.panel-section .mx-groupbox-header > span:not(.mx-groupbox-collapse-icon),
.panel-section .mx-groupbox-header > div {
    display: -webkit-box !important;
    -webkit-box-orient: vertical !important;
    -webkit-line-clamp: 1 !important;
    flex: 1 0 0 !important;
    
    overflow: hidden !important;
    color: #1E1E1E !important;
    text-overflow: ellipsis !important;
    
    font-family: "Segoe UI" !important;
    font-size: 18px !important;
    font-style: normal !important;
    font-weight: 600 !important;
    line-height: 24px !important;
    
    margin: 0 !important;
    padding: 0 !important;
}

/* ========================================
   PANEL SECTION - HOVER & FOCUS STATES
   ======================================== */

/* Header hover - text color */
.panel-section .mx-groupbox-header:hover {
    color: #007993 !important;
}

/* Header hover - inner text color */
.panel-section .mx-groupbox-header:hover .mx-groupbox-header-content,
.panel-section .mx-groupbox-header:hover > span:not(.mx-groupbox-collapse-icon),
.panel-section .mx-groupbox-header:hover > div {
    color: #007993 !important;
}

/* Header hover - icon tint to match link color */
.panel-section .mx-groupbox-header:hover .mx-groupbox-collapse-icon {
    filter: brightness(0) saturate(100%) invert(38%) sepia(93%) saturate(1087%) hue-rotate(157deg) brightness(91%) contrast(101%) !important;
    transition: filter 0.2s ease !important;
}

/* Focus-within - highlight panel border */
.panel-section:focus-within {
    border: 1px solid #149EEB !important;
    border-radius: 2px !important;
}

/* Default border */
.panel-section {
    border: 1px solid rgba(0, 0, 40, 0.20) !important;
    border-radius: 2px !important;
    transition: border-color 0.2s ease !important;
}

/* ========================================
   PANEL SECTION - SIGN BUTTON (HEADER)
   Absolutely positioned inside the header
   ======================================== */
.panel-section .btn-sign {
    position: absolute !important;
    top: 8px !important;
    right: 8px !important;
    z-index: 10 !important;
    margin: 0 !important;

    color: #FFFFFF !important;
    background: #003750 !important;
    border: 1px solid #003750 !important;
    
    width: 87px !important;
    height: 40px !important;
    min-width: 87px !important;
    max-width: 87px !important;
    
    padding: 4px 8px !important;
    border-radius: 2px !important;
    
    &:hover {
      background: #004A6B !important;
    }

    &:active {
      background: #003750 !important;
    }

    &:focus {
      background: #005F87 !important;
      color: #FFFFFF !important;
    }
}

/* Disabled state */
.panel-section .btn-sign.disabled-button {
    pointer-events: none !important;
    cursor: not-allowed !important;
    background: rgba(0, 0, 0, 0.15) !important;
    border: 1px solid rgba(0, 0, 0, 0.30) !important;
    color: rgba(0, 0, 0, 0.3) !important;
    width: 87px !important;
    height: 40px !important;
    padding: 4px 8px !important;
    border-radius: 2px !important;
}

/* Active / clickable state */
.panel-section .btn-sign:not(.disabled-button) {
    width: 87px !important;
    height: 40px !important;
    padding: 4px 8px !important;
    border-radius: 2px !important;
    cursor: pointer !important;
}

/* ========================================
   PANEL SECTION - BODY
   Single scroll container, body handles all overflow
   ======================================== */
.panel-section .mx-groupbox-body {
    width: 100% !important;
    max-width: 100% !important;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px !important;
    margin: 0 !important;
    box-sizing: border-box;
    padding: 8px !important;

    flex: 1 !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    min-height: 0 !important;
}

/* Remove top padding for groupBox1 body only */
.panel-section.mx-name-groupBox1 .mx-groupbox-body {
    padding-top: 0 !important;
}

/* Workarea type container inside groupBox1 */
.panel-section.mx-name-groupBox1 .mx-groupbox-body > .workarea-type-container {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    gap: 16px !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
