}

/* Remove form group spacing inside panel */
.panel-section .form-group {
    margin-bottom: 0 !important;
    margin-top: 0 !important;
}

/* ========================================
   PANEL SECTION - WORKAREA CONTAINER
   Flex wrap row layout for workarea items
   ======================================== */
.panel-section .mx-groupbox-body > .workarea-container {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    gap: 8px !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
}

/* ========================================
   PANEL SECTION - WORKAREA TYPE TILE
   Fixed 328px × 40px tile, no grow/shrink
   ======================================== */
.panel-section .workarea-container > .workarea-type {
    width: 328px !important;
    max-width: 328px !important;
    height: 40px !important;
    min-height: 40px !important;
    max-height: 40px !important;
    flex: 0 0 328px !important;
    overflow: hidden !important;
}

/* All body children take full width */
.panel-section .mx-groupbox-body > * {
    width: 100% !important;
    max-width: 100% !important;
}

/* Form elements take full width */
.panel-section input,
.panel-section textarea,
.panel-section select,
.panel-section .mx-textbox,
.panel-section .mx-textarea {
    width: 100% !important;
    box-sizing: border-box;
}

/* ========================================
   PANEL SECTION - GALLERY CONTENT
   No scroll here - parent body handles it
   ======================================== */
.panel-section .widget-gallery-content {
    position: relative !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
    max-height: 290px !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
}

/* ========================================
   WORKAREA TYPE TILE
   ======================================== */
.workarea-type {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  
  background-color: #ffffff;
  padding: 16px;
  gap: 8px;
  
  width: 230px;
  height: 56px;
  max-width: 230px;
  max-height: 56px;

  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.15);
  background: #FFF;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.30);
  
  user-select: none;
  cursor: pointer;
  
  margin: 8px;
  max-width: 328px;
  vertical-align: top;

  /* Hover - only when not selected or disabled */
  &:hover:not(.selected-button):not(.disabled-button) {
    background-color: #FFFFFF !important;
    background: #FFFFFF !important;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12) !important;
    border-color: #5a79c8;
  }

  /* Focus - only when not selected or disabled */
  &:focus-within:not(.selected-button):not(.disabled-button) {
    background-color: #FFFFFF !important;
    background: #FFFFFF !important;
    border: 2px solid #0F789B;  
    border-radius: 3px;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.3) !important;
  }

  & > * {
    margin: 0;
  }

  /* Default state */
  &.default-btn {
    background-color: white;
    color: #1E1E1E;
  }

  /* Selected state */
  &.selected-button {
    background: #EEF6F8 !important;
    background-color: #EEF6F8 !important;
    border: 1px solid rgba(0, 0, 0, 0.15) !important;

    &:hover {
      background: #daecf0 !important;
      background-color: #daecf0 !important;
      box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12) !important;
    }

    &:focus-within {
      background: #EEF6F8 !important;
      background-color: #EEF6F8 !important;
      border: 2px solid #0F789B !important;
      border-radius: 3px !important;
    }

    .checkbox-image img,
    .checkbox-image svg {
      filter: none;
    }
  }

  /* Disabled state */
  &.disabled-button {
    pointer-events: none !important;
    cursor: not-allowed !important;
    background-color: rgba(0, 0, 0, 0.05) !important;
    border: 1px solid rgba(0, 0, 0, 0.15) !important;
    color: rgba(0, 0, 0, 0.3) !important;
    box-shadow: none !important;

    .tile-title,
    .container-name-text,
    .mx-text {
      color: rgba(0, 0, 0, 0.3) !important;
    }

    .checkbox-image img,
    .checkbox-image svg {
      opacity: 0.3 !important;
      filter: grayscale(100%) !important;
    }

    &:hover {
      background: rgba(0, 0, 0, 0.15) !important;
      border-color: rgba(0, 0, 0, 0.15) !important;
      box-shadow: none !important;
    }
  }

  /* Icon */
  .checkbox-image {
    position: static;
    margin: 0;
    background-color: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    cursor: pointer;
    filter: none;
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    
    img, svg {
      width: 24px;
      height: 24px;
      display: block;
      object-fit: contain;
      transition: filter 0.2s ease, opacity 0.2s ease;
    }
  }

  /* Tile label text */
  .tile-title {
    flex: 1 0 0;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    margin: 0;
    padding: 0;
    
    color: #1E1E1E;
    font-family: "Segoe UI";
    font-size: 17.28px;
    font-style: normal;
    font-weight: 700;
    line-height: 23px;
    
    word-wrap: break-word;
    overflow-wrap: break-word;
    transition: color 0.2s ease;
  }
}

/* ========================================
   SEARCH BAR - DISABLED STATE
   ======================================== */

/* Disabled container */
.container-search-bar-parent.disabled-container {
    border-radius: 3px;
    border: 1px solid rgba(0, 0, 0, 0.15);
    background: rgba(0, 0, 0, 0.05);
    box-shadow: none !important;
    cursor: not-allowed !important;
}

/* Disabled input */
.container-search-bar-parent.disabled-container input.form-control {
    background: transparent !important;
    color: #6b7280 !important;
    cursor: not-allowed !important;
    border: none !important;
    pointer-events: none !important;
}

/* Disabled placeholder text */
.container-search-bar-parent.disabled-container input.form-control::placeholder {
    color: #9ca3af !important;
    opacity: 0.7 !important;
}

/* Disabled search icon */
.container-search-bar-parent.disabled-container .search-icon {
    opacity: 0.2 !important;
    cursor: not-allowed !important;
}

/* ========================================
   WORKAREA GALLERY - CHECKBOX RESET
   Remove default checkbox padding and float
   ======================================== */
.mx-page .workarea-gallery .checkbox-icon.mx-checkbox,
.mx-page .widget-gallery-item .checkbox-group .checkbox-icon.mx-checkbox {
  padding: 0 !important;
  padding-top: 0 !important;
  margin: 0 !important;
  margin-bottom: 0 !important;
  float: none !important;
}

.mx-page .workarea-gallery .checkbox-icon.form-group,
.mx-page .widget-gallery-item .checkbox-group .form-group {
  margin: 0 !important;
  margin-bottom: 0 !important;
}

/* ========================================
   WORKAREA GALLERY - GRID LAYOUT
   Auto-fill columns at 284px, left-aligned
   ======================================== */
.workarea-gallery.widget-gallery .widget-gallery-items.widget-gallery-lg-1 {
    display: grid !important;
    grid-template-columns: repeat(auto-fill, 284px) !important;
    column-gap: 16px !important;
    row-gap: 0px !important;
    justify-content: start !important;
    width: 100% !important;
    padding: 0 0 2px 0 !important;
    margin: 0 !important;
}

/* ========================================
   WORKAREA GALLERY - BASE STYLES
   ======================================== */
.workarea-gallery {
  
  /* Icon container */
  .checkbox-image {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 24px;
    height: 24px;
    padding: 0 !important;
    flex-shrink: 0;
    
    img, svg {
      width: 24px !important;
      height: 24px !important;
      display: block;
      object-fit: contain;
    }
  }

  /* Dimmed icon inside disabled tiles */
  .disabled-container .checkbox-image img,
  .disabled-container .checkbox-image svg {
    opacity: 0.3 !important;
    filter: grayscale(100%) !important;
  }
  
  /* Tile card container */
  .checkbox-group {
    display: flex !important;
    width: 284px !important;
    height: auto !important;
    min-height: 56px !important;
    max-height: none !important;
    padding: 16px !important;
    
    justify-content: flex-start !important;
    align-items: flex-start !important;
    align-content: flex-start !important;
    overflow: hidden;
    
    gap: 4px !important;
    flex-wrap: wrap !important;
    
    position: relative;
    background-color: #EEF6F8;
    background: #EEF6F8;
    
    border: 1px solid rgba(0, 0, 0, 0.15);
    border-radius: 3px;
    
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.30);
    
    user-select: none;
    transition: box-shadow .2s ease, border-color .2s ease;
    
    margin-left: 0px;
    margin-top: 16px;
    margin-right: auto;

    /* Hover - only when not disabled */
    &:not(.disabled-container):hover {
        box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
        border-color: #5a79c8;
    }

    /* Focus - only when not disabled */
    &:not(.disabled-container):focus-within {
        border: 2px solid #0F789B;  
        border-radius: 3px;
        box-shadow: 0px 1px 2px rgba(0, 0, 0, 0.3);
    }

    & > * {
        margin: 0;
    }
  }

  /* ========================================
   PROPERTY ROW - Label + Value
   Second row inside a tile/checkbox-group
   ======================================== */
  .property-container {
      display: flex;
      flex-direction: row;
      align-items: center;
      align-self: stretch;
      width: 100%;
      flex: 0 0 100%;
      margin-top: 4px;
      gap: 16px;
      min-width: 0;
      overflow: hidden;
  }

  .property-label {
      color: #464646;
      font-family: "Segoe UI";
      font-size: 12px;
      font-style: normal;
      font-weight: 400;
      line-height: 16px;
      flex-shrink: 0;
  }

  .property-value {
      color: #1E1E1E;
      font-family: "Segoe UI";
      font-size: 14.4px;
      font-style: normal;
      font-weight: 600;
      line-height: 19px;

      /* Truncation */
      flex: 1 1 0;
      min-width: 0;
      overflow: hidden;
  }

  /* Pass truncation down through tooltip wrapper */
  .property-value .widget-tooltip-trigger {
      display: block;
      min-width: 0;
      overflow: hidden;
  }

  /* Final truncation on the actual text span */
  .property-value .widget-tooltip-trigger span,
  .property-value .container-name-text {
      display: block;
      min-width: 0;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
  }

  /* Remove float from checkbox */
  .checkbox-icon.pull-left {
    float: none !important;
  }

  /* Checkbox element */
  .checkbox-icon {
    position: static;
    margin: 0;
    background-color: transparent;
    display: flex;
    align-items: center !important;
    justify-content: center !important;
    padding: 3px !important;
    cursor: pointer;
