.EProcedure {
  /* --- CSS Variables for common values --- */
  --color-white: #FFFFFF;
  --color-black-transparent-4d: #0000004D;
  --color-black-transparent-26: #00000026;
  --color-gray-ddd: #ddd;
  --color-gray-464646: #464646;
  --color-gray-1e1e1e: #1e1e1e;
  --color-blue-focus-outline: #005F87;
  --color-blue-focus-border: #0F789B;
  --color-blue-hover-light: #DAECF0;
  --color-blue-active-light: #CDE6EB;
  --color-blue-selected: #d0e7ee;
  --color-blue-outline-0f789b: #0f789b;
  --color-scrollbar-thumb: #888;
  --color-scrollbar-track: #f1f1f1;

  /* Button Success States (using existing var names for consistency) */
  --Buttons-Accent-Success-enabled-light: #0A9B00;
  --Buttons-Accent-Success-border-light: #054A00;
  --Buttons-Accent-Success-hover-light: #1D731C;
  --Buttons-Accent-Success-pressed-light: #054A00;

  /* Button Error States (using existing var names for consistency) */
  --Buttons-Accent-Error-enabled-light: #DC0000;
  --Buttons-Accent-Error-border-light: #840000;
  --Buttons-Accent-Error-hover-light: #B00000;
  --Buttons-Accent-Error-pressed-light: #840000;

  /* Common Font Styles */
  --font-segoe-ui-600-17-3-23: normal normal 600 17.3px / 23px Segoe UI;
  --font-segoe-ui-normal-12-16: normal 12px / 16px Segoe UI;
  --font-segoe-ui-600-14-4: 600 14.4px / normal Segoe UI;
  --font-segoe-ui-400-12: 400 12px / normal Segoe UI;

  /* Common Box Shadows */
  --box-shadow-sm: 0px 1px 2px 0px var(--color-black-transparent-4d);
  --box-shadow-md: 0px 1px 6px 0px var(--color-black-transparent-4d);

  /*-----------------------------------------------------Split Pane Starts------------------------------------------------------------*/
  .splitPane-Outer {
    zoom: 150%;

    .Pane {
      width: 50% !important;
      scrollbar-width: thin !important;
    }

    .Pane1 {
      flex: 0 0 40% !important;
    }

    .Max_Min_Button {
      float: right;
      position: relative;
      z-index: 100;
    }

    .clearfix {
      clear: both;

      &::after {
        content: "";
        display: table;
        clear: both;
      }
    }

    .hidepane {
      flex: 0 0 auto !important;
      display: none !important;
    }

    .showpane {
      flex: 1 1 100% !important;
      width: 100% !important;
      display: block !important;
    }

    .left-maximized {
      .Pane1 {
        flex: 1 1 100% !important;
        width: 100% !important;
        display: block !important;
      }

      .Pane2 {
        flex: 0 0 auto !important;
        display: none !important;
      }
    }

    .instructionPane {
      flex: 0 0 40% !important;
    }

    .instructionPanelContainer {
      top: 8px;
      position: relative;
    }

    .taskWorkAreaPanelContainer,
    .documentPanelContainer {
      top: -40px;
      position: relative;
    }

    .splitPane-Inner .Pane2 {
      overflow: hidden;
    }
  }

  /*-----------------------------------------------------Split Pane Ends------------------------------------------------------------*/

  /* --- General Button Styles --- */
  /* Base button styling for Pass/Fail/Submit/Reset */
  .PassBtn,
  .FailBtn,
  .Eproc_Submit {
    height: 40px;
    font: var(--font-segoe-ui-600-17-3-23);
    color: var(--color-white);
    box-shadow: var(--box-shadow-sm);
  }

  .Eproc_Reset {
    height: 40px;
    font: var(--font-segoe-ui-600-17-3-23);
    box-shadow: var(--box-shadow-sm);
  }

  /* Pass Button Specifics */
  .PassBtn {
    width: 98px;
    background: var(--Buttons-Accent-Success-enabled-light);
    border: 1px solid var(--Buttons-Accent-Success-border-light);

    &:hover {
      background: var(--Buttons-Accent-Success-hover-light);
      border-color: var(--Buttons-Accent-Success-border-light);
      box-shadow: var(--box-shadow-md);
    }

    &:active {
      background: var(--Buttons-Accent-Success-pressed-light);
      border-color: var(--Buttons-Accent-Success-border-light);
      box-shadow: var(--box-shadow-sm);
    }

    &:focus {
      background: var(--Buttons-Accent-Success-enabled-light);
      border: 1px solid var(--Buttons-Accent-Success-border-light) !important;
      outline: 2px solid var(--color-blue-focus-outline) !important;
      box-shadow: var(--box-shadow-sm);
    }
  }

  /* Fail Button Specifics */
  .FailBtn {
    width: 98px;
    background: var(--Buttons-Accent-Error-enabled-light);
    border: 1px solid var(--Buttons-Accent-Error-border-light);

    &:hover {
      background: var(--Buttons-Accent-Error-hover-light);
      border-color: var(--Buttons-Accent-Error-border-light);
      box-shadow: var(--box-shadow-md);
    }

    &:active {
      background: var(--Buttons-Accent-Error-pressed-light);
      border-color: var(--Buttons-Accent-Error-pressed-light);
      box-shadow: var(--box-shadow-sm);
    }

    &:focus {
      background: var(--Buttons-Accent-Error-enabled-light);
      border: 1px solid var(--Buttons-Accent-Error-border-light) !important;
      outline: 2px solid var(--color-blue-focus-outline) !important;
      box-shadow: var(--box-shadow-sm);
    }
  }

  .Eproc_Submit {
    width: 117px;
  }

  .Eproc_Reset {
    margin-right: 8px;
    width: 117px;
  }

  .disable-submit-btn {
    pointer-events: none;
    opacity: 50%;
  }

  .ComponentIssue-submit-btn {
    flex-direction: row-reverse;
    justify-content: flex-start;
    position: fixed;
    bottom: 6px;
    right: 48px;
    margin-top: -26vh;
    margin-right: 16px;
  }

  /* --- Checkbox Focus State --- */
  .FocusStateEprocCheckBoxCont {
    width: 50%;
  }

  .FocusStateEprocCheckBoxBtn {
    margin-left: 0px !important;
    width: 50%;

    >[class*="col-sm-9"] {
      padding-left: 0px !important;
      padding-right: 0px !important;
      max-width: 100% !important;
      white-space: nowrap;

      label {
        width: 50%;
      }

      input[type=checkbox] {
        margin-left: 0px !important;
      }
    }

    &:focus-within {
      outline: 2px solid var(--color-blue-outline-0f789b);
      opacity: 1;
      max-width: fit-content;
      width: 100%;
      padding: 1px;
    }
  }

  /* --- Data Collection & Warning --- */
  .dataCollectionExpanded {
    max-height: 35vh;
    overflow: auto;
  }

  .disposition_details_warning {
    zoom: 150%;
    position: fixed;
    top: 50%;
    left: 50%;
    width: 400px;
    height: 400px;
    margin-top: -5%;
    margin-left: -20%;
  }

  /* --- Tab Content Styling --- */
  div.tab-content.mx-tabcontainer-content {

    div.mx-name-task_instruction_container,
    div.mx-name-tasklist_instruction_container {
      overflow: auto;
      min-height: 275px;
      height: calc(100vh - 535px);
      scrollbar-color: var(--color-scrollbar-thumb) var(--color-scrollbar-track);

      .widget-html-element {
        margin-left: 18px;
        margin-right: 18px;
      }
    }
  }

  /*-----------------------------------------------------Document Viewer Starts------------------------------------------------------------*/
  .document-viewer-split-pane {
    height: 100%;
    display: flex;
    flex-direction: column;

    .document-viewer-split-pane .Pane2 {
      overflow-x: hidden !important;
    }

    div {
      flex: 0 1 auto; // Settings all the div's to height 100%
    }

    .widget-carousel div {
      // Settings all the div's inside widget-carousel to specified height
      flex: 0 0 auto;
    }

    .carousel-container
    {
      margin-top: 5px;
    }

    .documentViewer {

      .documentViewerTab ul.nav-tabs li:first-child {
        padding: 0;
      }

      .document-viewer-header {
        margin: auto;
        width: 100%;
        display: grid;
        grid-template-columns: 1fr 2fr;
        height: 40px;
      }

      .document-header-border {
        border-bottom: 1px solid var(--color-black-transparent-26);
        margin-left: 10px;
        margin-right: 10px;
        clear: both;
      }

      .doc-view-title {
        height: fit-content;
        margin-top: 4px;
      }

      .documentViewerTab {
        width: 100%;
        // max-height: 45vh;
        display: flex;
        flex-direction: column;

        .tab-content {
          overflow-x: hidden;
          overflow-y: hidden;
          scrollbar-width: thin;
        }
      }

      .documentViewTypeButtonContainer {
        float: right;
        margin-right: 48px;
        top: -8px;
        position: relative;
        text-align: right;

        button {
          padding: 6px;

          &:hover {
            background-color: var(--color-blue-hover-light) !important;
          }

          &:focus {
            border: 2px solid var(--color-blue-focus-outline) !important;
          }

          &:active {
            background-color: var(--color-blue-active-light) !important;
          }
        }
      }

      .document-icon {
        display: flex;
        align-items: center;
        justify-content: center;
        margin-right: 8px;

        img {
          width: 48px;
          height: 48px;
        }
      }

      .documentListContainer {
        overflow: auto;
        height: 46vh;
        scrollbar-width: thin;

        .doc-item {
          display: flex;
          align-items: center;
          padding: 10px;
          background-color: var(--color-white);
          border-bottom: 1px solid var(--color-gray-ddd);

          /* Column padding override for doc-item children */
          [class*="col-"] {
            padding-left: 0 !important;
            padding-right: 0 !important;
          }


          .document-details {
            flex: 1;
            overflow: hidden;
            padding-right: 10px !important;

            .document-name {
              font: var(--font-segoe-ui-600-14-4);
              color: #000000;
              margin-bottom: 2px;

              span {
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
                display: block;
              }
            }

            .document-description {
              font: var(--font-segoe-ui-400-12);
              color: var(--color-gray-464646);

              .descriptionDiv {
                cursor: auto;
              }

              span {
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
                display: block;
              }
            }
          }

          .document-action {
            margin-left: auto;
            display: flex;
            align-items: center;
            justify-content: center;

            a {
              padding-left: 0px;
            }

            img {
              width: 24px;
              height: 24px;
            }
          }

          /* Doc Item States */
          &:hover {
            background-color: var(--color-blue-hover-light) !important;
          }

          &:active {
            background-color: var(--color-blue-active-light) !important;
          }

          &:focus {
            border: 2px solid var(--color-blue-focus-border) !important;
          }

          &.selected {
            background-color: var(--color-blue-selected);
          }
        }
      }

      .widget-gallery .widget-gallery-items.widget-gallery-lg-1 {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
        justify-content: start;
        gap: 8px;
      }

      /*-----------------------------------------------------Document Pre-View Starts------------------------------------------------------------*/
      .documentPreViewContainer {
        margin-top: 4px;
        border: 1px solid var(--color-black-transparent-26);

        .docPreviewContainer {
          overflow: auto;
          overflow: hidden;
          height: 31vh;

          div.widget-document-viewer {
            border: 0;
            border-radius: 0;
          }

          .widget-document-viewer-content {
            scrollbar-width: thin;
          }


          .documentPreview {
            width: 100%;
            height: 100%;
            display: flex;
            text-align: center;
            align-items: center;
            justify-content: center;
            flex: 1;
            overflow: auto;

            .docPreview-Title {
              background-color: red;
              width: 100%;
              text-align: left;
            }

            ._3dViewer {
              width: 100%;
              height: 100%;
            }

            .documentName {
              span {
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
                display: block;
                width: 130px;
              }
            }
          }


          .docNotSelectedText {
            font-family: "Segoe UI";
            font-style: italic;
            font-size: 17.28px;
            font-weight: 400;
            color: #6E6E6E;
            user-select: none;
            margin: 0;
          }

          .docSelectedText {
            position: absolute;
            top: 12px;
            left: 12px;

            font-family: "Segoe UI";
            font-size: 14.4px;
            font-weight: 600;
            color: #1E1E1E;

            margin: 0;
            padding: 0;
            z-index: 10;
          }

          .notSupportedContainer {
            img {
              width: 48px;
              height: 48px;
            }
          }

          .widget-document-viewer-controls {
            margin-right: 5px;


            .widget-document-viewer-pagination {
              margin-top: -4px;
              
              .btn-icon-only{
                height: 25px;
                width: 25px;
              }
              
            }
            input[type="text"] {
              width: 25px;
              height: 20px;
              margin: 5px;
              margin-top: 7px;
            }
            .icon-Download {
              font-size: x-large;
              border: none;
            }
          }

          .btn-open-in-new-tab {
            top: 0px;
          }

          .btn-open-in-new-tab img {
            font-size: x-large;
            width: 24px;
            height: 24px;
          }

        }

        .docPreviewFooter {
          position: fixed;
          bottom: -16px;
          margin-right: 10px;
          width: -webkit-fill-available;
        }

        .carouselMinWidth {
          width: 30%;
        }

        .carouselMedWidth {
          width: 50%;
        }

        .carouselMaxWidth {
          width: 100%;
        }
      }

      /*-----------------------------------------------------Document Pre-View Ends------------------------------------------------------------*/

    }

    .documentPanelContainer .docPreviewContainer .documentName span {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      display: block;
      width: 130px;
    }
  }

  /*-----------------------------------------------------Document Viewer Ends------------------------------------------------------------*/

  .ResourceDropdown .widget-customDropdown-holder {
    z-index: 101 !important;
  }

  .LocationDropdown .widget-customDropdown-holder {
    z-index: 100 !important;
  }

  .Max_Min_Button,
  .top-right-action-button,
  div.widget-document-viewer-controls-icons button {
    width: 48px;
    height: 48px;
    background: transparent;
    box-shadow: none;
    border: 2px solid transparent;
    transition: border-color 0s ease;

    &:focus {
      background-color: transparent !important;
      border: 2px solid var(--color-blue-focus-outline) !important;
      outline: none !important;
    }

    &:hover {
      background-color: var(--color-blue-hover-light);
      border: 2px solid transparent;
      box-shadow: none !important;
      outline: none !important;
    }

    &:active {
      background-color: var(--color-blue-active-light) !important;
      outline: none !important;
      border: 0;
    }

    img {
      width: 24px;
      height: 24px;
    }
  }

  div.widget-document-viewer-controls button {
    margin: 0;
  }

  div.widget-document-viewer-controls-icons button {
    font-size: x-large;
  }

  .docpane_min {
    img {
      height: 36px;
      width: 28px;
    }
  }

  /* ------- Topbar menu Override ------------------------------- */
  .backButton {
    left: 48px !important;
  }

  div.menuWrapper:has(button[class*="mx-name-menuButton"]),
  div.menuWrapper:has(button[class*="mx-name-menuCloseButton"]) {
    .backButton {
      left: 96px !important;
    }
  }

  .app-identity label {
    margin-left: 5px !important;
  }
}

