		width: 100%;
		height: 32px;
		display: flex;
		flex-direction: column;
		align-items: center;
		justify-content: center;
		padding: 16px;
		border-width: 1px 0px 1px 0px;
		border-style: solid;
		border-color: #93dced;

		&_title {
			margin-top: 16px;
			font: bold normal normal 17px/23px Segoe UI;
			font-weight: 500;
		}

		&_text {
			color: #464646;
			font: normal normal 12px/16px Segoe UI;
			font-weight: 400;
		}
	}

	.application-header {
		font-size: 24px !important;
		color: #FFF !important;
	}

	label {
		font: normal normal var(--font-weight-default) var(--font-size-default)/var(--line-height-default) Segoe UI;
		letter-spacing: 0px;
		color: #1E1E1E;
		opacity: 1;
	}

	span.mx-text {
		font: normal normal normal var(--font-size-default)/var(--line-height-default) Segoe UI;
		letter-spacing: 0px;
		color: #464646;
		opacity: 1;
	}

	.ux-rquired-input-field:before {
		content: '';
		background: url("/img/EXCR_DesignSystem$Icon_Repository$indicatorRequired16.svg");
		background-size: var(--icon-width-compact) var(--icon-height-compact);
		background-repeat: no-repeat;
		background-position-y: 20%;
		width: 11px;
		height: 32px;
		display: inline-block;
		margin-bottom: -20px;
	}

	input[type="text"],
	input[type="password"] {
		text-align: left;
		font: normal normal normal var(--font-size-default)/var(--line-height-default) Segoe UI;
		letter-spacing: 0px;
		color: #1e1e1e;
		padding: 8px;
		background: #FFFFFF 0% 0% no-repeat padding-box;
		border: 1px solid #828282;
		border-radius: 1px;
		opacity: 1; // Kept the last declaration
		min-width: var(--panel-content-area);

		&:disabled {
			background: rgba(0, 0, 0, 0.15) 0% 0% no-repeat padding-box !important;
			border: 1px solid rgba(0, 0, 0, 0.3);
			border-radius: 2px;
			opacity: 1;
		}

		&:enabled:hover {
			background: #FFFFFF 0% 0% no-repeat padding-box;
			border: 2px solid #828282;
			border-radius: 2px;
			opacity: 1;
		}

		&:enabled:focus {
			background: #FFFFFF 0% 0% no-repeat padding-box;
			border: 2px solid #3296b9;
			border-radius: 2px;
			opacity: 1;
		}

		&:enabled:active {
			background: #FFFFFF 0% 0% no-repeat padding-box;
			border: 2px solid #3296b9;
			border-radius: 2px;
			opacity: 1;
		}
	}


	.ContainerScanInput {
		margin-bottom: 0px;
		width: var(--panel-content-area);

		.form-control {
			padding: 8px;
			gap: 4px;
			border: 1px solid var(--Controls-Input-border-light, #828282);
			width: var(--panel-content-area);
			height: 32px;

			&:hover {
				box-shadow: inset 0 0 0 2px #8c8c8c;
				border-radius: 2px;
				opacity: 1;
			}

			&:focus {
				box-shadow: inset 0 0 0 2px #3296b9;
				border-radius: 2px;
				opacity: 1;
			}

			&:active {
				box-shadow: inset 0 0 0 2px #3296b9;
				border-radius: 2px;
				opacity: 1;
			}
		}
	}

